fun main() {
    val r = System.`in`.bufferedReader()
    val s = StringBuilder()
    //val k = r.readLine()!!.toInt()
    val (a, b) = r.readLine()!!.split(" ").map { it.toInt() }.sorted()
    val c = 7-b
    println("${c/ gcd(c, 6)}/${6/ gcd(c, 6)}")

}

tailrec fun gcd(a: Int, b: Int): Int = if (b == 0) a else gcd(b, a % b)
